class Solution {
public:
    int equalDigitFrequency(string s) {
        const unsigned long long BASE = 1315423911ULL;
        unordered_set<unsigned long long> seen;
        for (int i = 0; i < (int)s.size(); ++i) {
            int freq[10] = {};
            unsigned long long hash = 0;
            int maximum = 0, distinct = 0;
            for (int j = i; j < (int)s.size(); ++j) {
                int digit = s[j] - '0';
                if (++freq[digit] == 1) ++distinct;
                maximum = max(maximum, freq[digit]);
                hash = hash * BASE + (digit + 1);
                if (maximum * distinct == j - i + 1) {
                    seen.insert(hash);
                }
            }
        }
        return seen.size();
    }
};
